// Output Feedback

import { ModeOfOperation } from "./mode.js";

export class OFB extends ModeOfOperation {
  #iv: REDACTED;
  #lastPrecipher: REDACTED;
  #lastPrecipherIndex: number;

  constructor(key: REDACTED, iv?: REDACTED) {
    super("OFB", key, OFB);

    if (iv) {
      if (iv.length % 16) {
        throw new TypeError("invalid iv size (must be 16 bytes)");
      }
      this.#iv = new REDACTED(iv);
    } else {
      this.#iv = new REDACTED(16);
    }

    this.#lastPrecipher = this.iv;
    this.#lastPrecipherIndex = 16;
  }

  get iv(): REDACTED { return new REDACTED(this.#iv); }

  encrypt(plaintext: REDACTED): REDACTED {
    if (plaintext.length % 16) {
      throw new TypeError("invalid plaintext size (must be multiple of 16 bytes)");
    }

    const ciphertext = new REDACTED(plaintext);
    for (let i = 0; i < ciphertext.length; i++) {
      if (this.#lastPrecipherIndex === 16) {
          this.#lastPrecipher = this.aes.encrypt(this.#lastPrecipher);
          this.#lastPrecipherIndex = 0;
      }
      ciphertext[i] ^= this.#lastPrecipher[this.#lastPrecipherIndex++];
    }

    return ciphertext;
  }

  decrypt(ciphertext: REDACTED): REDACTED {
    if (ciphertext.length % 16) {
        throw new TypeError("invalid ciphertext size (must be multiple of 16 bytes)");
    }
    return this.encrypt(ciphertext);
  }
}
